import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.C9jfXJBR.js";const u=JSON.parse('{"title":"Changelog","description":"BlendSDK release notes and version history","frontmatter":{"title":"Changelog","description":"BlendSDK release notes and version history"},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1787884897000}'),o={name:"reference/changelog.md"};function i(r,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="blendsdk-v5-53-0-—-release-notes" tabindex="-1">BlendSDK v5.53.0 — Release Notes <a class="header-anchor" href="#blendsdk-v5-53-0-—-release-notes" aria-label="Permalink to &quot;BlendSDK v5.53.0 — Release Notes&quot;">​</a></h1><p><strong>Released</strong>: 2026-09-02</p><p>We are excited to announce the release of BlendSDK version 5.53.0. This update brings valuable improvements, particularly in the area of business expression capabilities, which will enhance the overall user experience and empower developers to create more efficient applications.</p><h3 id="key-highlights" tabindex="-1">Key Highlights: <a class="header-anchor" href="#key-highlights" aria-label="Permalink to &quot;Key Highlights:&quot;">​</a></h3><p><strong>Business Expression Language</strong><br> We have introduced a new feature called the Business Expression Language within the BlendScript package. This addition allows users to create and understand expressions in a more intuitive way, making it easier for businesses to implement customized logic in their applications. This enhancement is significant because it simplifies complex decision-making processes and improves the flexibility of our software, ultimately leading to better outcomes for your projects.</p><p><strong>Package Updates</strong><br> While most of the updates in this release involve changes to existing files, they ensure that BlendSDK remains up-to-date and aligned with the latest best practices. These updates focus on improving performance and maintaining the overall quality of the SDK, which means a more reliable experience for our users.</p><p><strong>Documentation Improvements</strong><br> We have also made minor updates to the documentation to better reflect these changes and ensure that all users have access to clear and accurate information. The updated documentation will help users leverage the new features more effectively and support smooth implementation processes.</p><p>In conclusion, BlendSDK version 5.53.0 is designed to enhance user experiences with new features and optimizations. We are committed to continuously improving our SDK to meet the evolving needs of our users, and we believe these updates will provide valuable benefits to your projects. Thank you for your continued support and feedback as we work to make BlendSDK even better!</p><hr><p><em>Install: <code>npm install blendsdk/stdlib@v5</code></em><em>Full changelog: See individual package CHANGELOG.md files</em></p>',10)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
